package io.github.rebrowser.crypto;
import static org.junit.Assert.*;
import java.nio.ByteBuffer;
import java.security.GeneralSecurityException;
import java.util.Arrays;
import org.junit.Test;
/** Actual JCA private metadata format, public TOY key only; no Android key/store/authority. */
public final class PrivateRecordSealerTest {
 private static byte[] key(){return new byte[32];}
 private static PrivateRecordSealer.Binding binding(){return new PrivateRecordSealer.Binding(PrivateRecordSealer.Purpose.BROWSER_CATALOG,new byte[16],new byte[16],1);}
 @Test public void emptyRecordRoundTripAndExactOverhead()throws Exception{byte[] sealed=PrivateRecordSealer.seal(key(),binding(),new byte[0]);assertEquals(88,sealed.length);assertArrayEquals(new byte[0],PrivateRecordSealer.open(key(),binding(),sealed));}
 @Test public void binaryExactOriginalRoundTripForBothPurposes()throws Exception{byte[] data=new byte[65537];for(int i=0;i<data.length;i++)data[i]=(byte)i;for(PrivateRecordSealer.Purpose p:PrivateRecordSealer.Purpose.values()){PrivateRecordSealer.Binding b=new PrivateRecordSealer.Binding(p,new byte[16],new byte[16],18);byte[] bounded=Arrays.copyOf(data,Math.min(data.length,p.maximumPlaintextBytes()));assertArrayEquals(bounded,PrivateRecordSealer.open(key(),b,PrivateRecordSealer.seal(key(),b,bounded)));}}
 @Test public void noCallerPlaintextOrKeyMutation()throws Exception{byte[] k=key(),p={1,2,3},saved=p.clone();PrivateRecordSealer.seal(k,binding(),p);assertArrayEquals(key(),k);assertArrayEquals(saved,p);}
 @Test public void everySealUsesFreshNonce()throws Exception{assertFalse(Arrays.equals(PrivateRecordSealer.seal(key(),binding(),new byte[]{1}),PrivateRecordSealer.seal(key(),binding(),new byte[]{1})));}
 @Test public void fixedHeaderHasIndependentVersionPurposeRevisionAndLength()throws Exception{byte[] data=PrivateRecordSealer.seal(key(),binding(),new byte[]{1,2,3});ByteBuffer in=ByteBuffer.wrap(data);assertEquals(0x5242505249563100L,in.getLong());assertEquals(1,in.getShort());assertEquals(1,in.getShort());assertEquals(1,in.getInt());assertEquals(1,ByteBuffer.wrap(data,48,8).getLong());assertEquals(3,ByteBuffer.wrap(data,56,4).getInt());assertEquals(91,data.length);}
 @Test public void differentEpochRejected()throws Exception{byte[] wrong=new byte[16];wrong[0]=1;byte[] data=PrivateRecordSealer.seal(key(),binding(),new byte[]{1});assertThrows(GeneralSecurityException.class,()->PrivateRecordSealer.open(key(),new PrivateRecordSealer.Binding(binding().purpose(),wrong,new byte[16],1),data));}
 @Test public void differentScopeRejected()throws Exception{byte[] wrong=new byte[16];wrong[0]=1;byte[] data=PrivateRecordSealer.seal(key(),binding(),new byte[]{1});assertThrows(GeneralSecurityException.class,()->PrivateRecordSealer.open(key(),new PrivateRecordSealer.Binding(binding().purpose(),new byte[16],wrong,1),data));}
 @Test public void differentPurposeRejected()throws Exception{byte[] data=PrivateRecordSealer.seal(key(),binding(),new byte[]{1});assertThrows(GeneralSecurityException.class,()->PrivateRecordSealer.open(key(),new PrivateRecordSealer.Binding(PrivateRecordSealer.Purpose.GECKO_CHECKPOINT,new byte[16],new byte[16],1),data));}
 @Test public void differentRevisionRejected()throws Exception{byte[] data=PrivateRecordSealer.seal(key(),binding(),new byte[]{1});assertThrows(GeneralSecurityException.class,()->PrivateRecordSealer.open(key(),new PrivateRecordSealer.Binding(binding().purpose(),new byte[16],new byte[16],2),data));}
 @Test public void differentKeyRejected()throws Exception{byte[] data=PrivateRecordSealer.seal(key(),binding(),new byte[]{1}),wrong=key();wrong[0]=1;assertThrows(GeneralSecurityException.class,()->PrivateRecordSealer.open(wrong,binding(),data));}
 @Test public void eachByteTamperRejectedBeforeAnyPlaintextReturn()throws Exception{byte[] data=PrivateRecordSealer.seal(key(),binding(),new byte[]{1,2,3});for(int i=0;i<data.length;i++){byte[] corrupt=data.clone();corrupt[i]^=1;assertThrows(GeneralSecurityException.class,()->PrivateRecordSealer.open(key(),binding(),corrupt));}}
 @Test public void truncationAndTrailingBytesNotAccepted()throws Exception{byte[] data=PrivateRecordSealer.seal(key(),binding(),new byte[]{1});assertThrows(IllegalArgumentException.class,()->PrivateRecordSealer.open(key(),binding(),new byte[87]));assertThrows(GeneralSecurityException.class,()->PrivateRecordSealer.open(key(),binding(),Arrays.copyOf(data,data.length+1)));}
 @Test public void purposeSizeLimitBeforeCipher()throws Exception{PrivateRecordSealer.Binding b=new PrivateRecordSealer.Binding(PrivateRecordSealer.Purpose.GECKO_CHECKPOINT,new byte[16],new byte[16],1);assertThrows(IllegalArgumentException.class,()->PrivateRecordSealer.seal(key(),b,new byte[2*1024*1024+1]));}
 @Test public void malformedNativeBindingAndKeysRejected(){assertThrows(IllegalArgumentException.class,()->new PrivateRecordSealer.Binding(null,new byte[16],new byte[16],1));assertThrows(IllegalArgumentException.class,()->new PrivateRecordSealer.Binding(binding().purpose(),new byte[15],new byte[16],1));assertThrows(IllegalArgumentException.class,()->new PrivateRecordSealer.Binding(binding().purpose(),new byte[16],new byte[16],0));assertThrows(IllegalArgumentException.class,()->PrivateRecordSealer.seal(new byte[31],binding(),new byte[0]));}
 @Test public void bindingAndAadDefensive(){byte[] epoch=new byte[16],scope=new byte[16];PrivateRecordSealer.Binding b=new PrivateRecordSealer.Binding(binding().purpose(),epoch,scope,1);epoch[0]=1;scope[0]=1;assertArrayEquals(new byte[16],b.dataEpoch());assertArrayEquals(new byte[16],b.nativeScope());byte[] aad=b.wrappingAad();aad[0]=0;assertNotEquals(aad[0],b.wrappingAad()[0]);assertEquals(58,b.wrappingAad().length);}
 @Test public void candidateRevisionDoesNotAuthenticateModifiedRecord()throws Exception{byte[] data=PrivateRecordSealer.seal(key(),binding(),new byte[]{1});ByteBuffer.wrap(data,48,8).putLong(9);assertEquals(9,PrivateRecordSealer.unverifiedRevision(data));assertThrows(GeneralSecurityException.class,()->PrivateRecordSealer.open(key(),new PrivateRecordSealer.Binding(binding().purpose(),new byte[16],new byte[16],9),data));}
 @Test public void negativeCandidateRevisionRejected()throws Exception{byte[] data=PrivateRecordSealer.seal(key(),binding(),new byte[0]);ByteBuffer.wrap(data,48,8).putLong(-1);assertThrows(IllegalArgumentException.class,()->PrivateRecordSealer.unverifiedRevision(data));}
}
